package main

import (
	"bytes"
	"strings"
	"testing"
)

// fixturePTX is hand-written in the shape NVRTC emits for forward.cu: one
// unsuffixed float32 entry point and its F16 and BF16 siblings. It is a
// fixture for the parser and the dtype check, not a record of a compilation:
// no PTX in this repository has been produced by a compiler on this machine.
const fixturePTX = `//
// Generated by NVIDIA NVVM Compiler
//
.version 8.3
.target sm_89
.address_size 64

.visible .entry LinearGEMV(
	.param .u64 LinearGEMV_param_0,
	.param .u64 LinearGEMV_param_1
)
{
	.reg .f32 	%f<4>;
	.reg .b64 	%rd<3>;

	ld.param.u64 	%rd1, [LinearGEMV_param_0];
	ld.global.nc.f32 	%f1, [%rd1];
	fma.rn.f32 	%f2, %f1, %f1, %f1;
	st.global.f32 	[%rd1], %f2;
	ret;
}

.visible .entry LinearGEMVF16(
	.param .u64 LinearGEMVF16_param_0
)
{
	.reg .f32 	%f<4>;
	.reg .b16 	%rs<3>;
	.reg .b64 	%rd<3>;

	ld.param.u64 	%rd1, [LinearGEMVF16_param_0];
	ld.global.nc.u16 	%rs1, [%rd1];
	cvt.f32.f16 	%f1, %rs1;
	fma.rn.f32 	%f2, %f1, %f1, %f1;
	st.global.f32 	[%rd1], %f2;
	ret;
}

.visible .entry LinearGEMVBF16(
	.param .u64 LinearGEMVBF16_param_0
)
{
	.reg .f32 	%f<4>;
	.reg .b32 	%r<3>;
	.reg .b64 	%rd<3>;

	ld.param.u64 	%rd1, [LinearGEMVBF16_param_0];
	ld.global.nc.u16 	%r1, [%rd1];
	shl.b32 	%r2, %r1, 16;
	fma.rn.f32 	%f2, %f1, %f1, %f1;
	st.global.f32 	[%rd1], %f2;
	ret;
}
`

func TestPTXKernelStats(t *testing.T) {
	stats, err := ptxKernelStats(fixturePTX)
	if err != nil {
		t.Fatal(err)
	}
	if len(stats) != 3 {
		t.Fatalf("got %d kernels, want 3", len(stats))
	}
	byName := map[string]ptxKernelStat{}
	for _, s := range stats {
		byName[s.Name] = s
	}
	for _, name := range []string{"LinearGEMV", "LinearGEMVF16", "LinearGEMVBF16"} {
		s, ok := byName[name]
		if !ok {
			t.Fatalf("kernel %s missing from the report", name)
		}
		if s.Instructions == 0 {
			t.Errorf("%s: no instructions counted", name)
		}
		if s.Mnemonics["fma"] != 1 {
			t.Errorf("%s: fma count = %d, want 1", name, s.Mnemonics["fma"])
		}
	}
	if got := byName["LinearGEMVF16"].Mnemonics["cvt"]; got != 1 {
		t.Errorf("F16 cvt count = %d, want 1", got)
	}
	if got := byName["LinearGEMV"].Mnemonics["cvt"]; got != 0 {
		t.Errorf("f32 kernel cvt count = %d, want 0", got)
	}
}

// TestCheckWeightKernelPTX is the point of the file: a name says which entry
// point was bound, and only the instructions say which weights it loads.
func TestCheckWeightKernelPTX(t *testing.T) {
	tests := []struct {
		name  string
		dtype WeightDType
		entry string
		want  string // substring of the expected error, empty for success
	}{
		{"f32 kernel has no conversion", WeightF32, "LinearGEMV", ""},
		{"f16 kernel converts", WeightF16, "LinearGEMVF16", ""},
		{"bf16 kernel shifts", WeightBF16, "LinearGEMVBF16", ""},
		{"f16 dtype on the f32 kernel", WeightF16, "LinearGEMV", "holds no cvt.f32.f16"},
		{"f32 dtype on the f16 kernel", WeightF32, "LinearGEMVF16", "holds 1 cvt.f32.f16"},
		{"bf16 dtype on the f16 kernel", WeightBF16, "LinearGEMVF16", "holds 1 cvt.f32.f16"},
		{"undefined entry point", WeightF16, "LinearGEMVF8", "not defined in the compiled ptx"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := checkWeightKernelPTX(fixturePTX, tt.dtype, tt.entry)
			if tt.want == "" {
				if err != nil {
					t.Fatalf("checkWeightKernelPTX = %v, want nil", err)
				}
				return
			}
			if err == nil {
				t.Fatalf("checkWeightKernelPTX = nil, want an error containing %q", tt.want)
			}
			if !strings.Contains(err.Error(), tt.want) {
				t.Errorf("error = %v, want it to contain %q", err, tt.want)
			}
		})
	}
}

func TestWritePTXReport(t *testing.T) {
	var buf bytes.Buffer
	if err := writePTXReport(&buf, fixturePTX); err != nil {
		t.Fatal(err)
	}
	out := buf.String()
	for _, want := range []string{"KERNEL", "LinearGEMVBF16", "LinearGEMVF16", "LinearGEMV"} {
		if !strings.Contains(out, want) {
			t.Errorf("report is missing %q:\n%s", want, out)
		}
	}
	// Sorted by name, so the report does not change between runs.
	if i, j := strings.Index(out, "LinearGEMVBF16"), strings.Index(out, "LinearGEMVF16"); i > j {
		t.Errorf("report is not sorted by kernel name:\n%s", out)
	}
}

func TestPTXReportRejectsGarbage(t *testing.T) {
	stats, err := ptxKernelStats("this is not ptx\n")
	if err != nil {
		t.Fatalf("ptxKernelStats = %v, want no error: the parser reports no kernels rather than failing", err)
	}
	if len(stats) != 0 {
		t.Errorf("got %d kernels from non-ptx input, want 0", len(stats))
	}
	if err := checkWeightKernelPTX("this is not ptx\n", WeightF16, "LinearGEMVF16"); err == nil {
		t.Error("checkWeightKernelPTX = nil for input defining no kernels, want an error")
	}
}

func TestTopMnemonicsIsStable(t *testing.T) {
	m := map[string]int{"ld": 3, "st": 3, "fma": 5, "cvt": 1, "ret": 1}
	if got, want := topMnemonics(m, 3), "fma=5 ld=3 st=3"; got != want {
		t.Errorf("topMnemonics = %q, want %q", got, want)
	}
}
